    int countCoprimeSelections(vector<vector<int>>& grid) {
        long long MOD = 1000000007;
        unordered_map<int, long long> dp;
        for (int x : grid[0]) {
            dp[x] = (dp[x] + 1) % MOD;
        }
        for (size_t r = 1; r < grid.size(); ++r) {
            unordered_map<int, long long> next_dp;
            for (auto& [g, ways] : dp) {
                for (int x : grid[r]) {
                    int new_g = gcd(g, x);
                    next_dp[new_g] = (next_dp[new_g] + ways) % MOD;
                }
            }
            dp = move(next_dp);
        }
        return dp[1] % MOD;
