import java.util.*;

class Solution {
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int countCoprimeSelections(int[][] grid) {
        long MOD = 1000000007;
        Map<Integer, Long> dp = new HashMap<>();
        for (int x : grid[0]) {
            dp.put(x, (dp.getOrDefault(x, 0L) + 1) % MOD);
        }
        for (int r = 1; r < grid.length; r++) {
            Map<Integer, Long> nextDp = new HashMap<>();
            for (Map.Entry<Integer, Long> entry : dp.entrySet()) {
                int g = entry.getKey();
                long ways = entry.getValue();
                for (int x : grid[r]) {
                    int newG = gcd(g, x);
                    nextDp.put(newG, (nextDp.getOrDefault(newG, 0L) + ways) % MOD);
                }
            }
            dp = nextDp;
        }
        return (int)(dp.getOrDefault(1, 0L) % MOD);
    }
}

var countCoprimeSelections = function(grid) {
    const MOD = 1000000007n;
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
    let dp = new Map();
    for (const x of grid[0]) {
        dp.set(x, ((dp.get(x) || 0n) + 1n) % MOD);
    }
    for (let r = 1; r < grid.length; r++) {
        const nextDp = new Map();
        for (const [g, ways] of dp.entries()) {
            for (const x of grid[r]) {
                const newG = gcd(g, x);
                nextDp.set(newG, ((nextDp.get(newG) || 0n) + ways) % MOD);
            }
        }
        dp = nextDp;
    }
    return Number((dp.get(1) || 0n) % MOD);
